function ENTROPY(p[1..n]):
    H <- 0
    for i in 1..n:
        if p[i] > 0:
            H <- H - p[i] * log(p[i])   # negMulLog(p[i])
        # else contribute 0 (0*log0 = 0 convention)
    return H

